checked.script:
(blockcontext, pageContext, item) => {
    let settings = blockcontext.timelineSettings;
    let enabled = (settings && settings.eventGrouping && (settings.eventGrouping.enabled === true)) ? true : false;
    return enabled;
}

label.script:
(blockcontext, pageContext, item) => {
    let settings = blockcontext.timelineSettings;
    if (settings && settings.eventGrouping.enabled === true)
        return 'Enabled';
    return 'Disabled';
}
